import{z as i,x as s,o as e,c as d,q as l,j as B,D as E,d as t,s as o,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"模型指纹","description":"","frontmatter":{"title":"模型指纹","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/model-fingerprinting.md","filePath":"llm/model-fingerprinting.md","lastUpdated":1791413859000}'),p={name:"llm/model-fingerprinting.md"};function m(C,a,F,h,c,f){const n=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=l('<h1 id="模型指纹" tabindex="-1">模型指纹 <a class="header-anchor" href="#模型指纹" aria-label="Permalink to &quot;模型指纹&quot;">​</a></h1><div class="epigraph"><p>特有的错误、特有的水印、特有的触发完成，可以当指纹。指纹证明「像」，很少单独证明「就是偷来的权重」。</p><footer>—— 对照水印与权重指纹文献；检测服务于提取与泄露，不是新的能力基准</footer></div><p><a href="/llm/model-extraction-attack">上一课</a>留下举证缺口。本课补指纹：用行为或权重上的独特模式，识别「这是不是那一家的模型 / 学生」。缺口不是评测排行，而是取证——误报会冤枉独立训练，漏报会放过提取。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开源微调、合并、量化会改变表面文风，但可能保留教师的特有缺陷或水印。产品需要：一组只有本模型（或本水印密钥）才会稳定表现的测试。公共基准题不能当指纹，人人都会。</p><p><span class="marginnote">指纹应在你控制的密钥或持有提示上，不应依赖「只有我们会答错这道著名题」——著名题会被下一版修掉，也会被别人碰巧答错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三类。<strong>水印</strong>：生成时嵌入统计模式，验证器持有密钥。<strong>触发完成</strong>：训练或系统层保留秘密前缀→固定短语（类似合法的后门，仅用于取证）。<strong>错误谱</strong>：在私有难例上的对错向量，比较学生与教师的相关。权重指纹（哈希、特定层统计）只适用于你仍能拿到参数的泄露场景。</p><p><span class="marginnote">直觉类比：水印像纸币里的防伪纤维——肉眼读不出、但持灯一照就有；秘密触发像只有本行知道的暗语；错误谱则像笔迹鉴定——不靠某个暗号，而靠「这份笔迹连容易写错的字都错得一样」。</span></p>',9)),(e(),B(A,null,{default:E(()=>[o(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%BE%85%E6%B5%8B%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20W%5B%22%E6%B0%B4%E5%8D%B0%E6%A3%80%E9%AA%8C%22%5D%0A%20%20M%20--%3E%20T%5B%22%E7%A7%98%E5%AF%86%E8%A7%A6%E5%8F%91%22%5D%0A%20%20M%20--%3E%20E%5B%22%E7%A7%81%E6%9C%89%E9%94%99%E8%AF%AF%E8%B0%B1%22%5D%0A%20%20W%20--%3E%20V%5B%22%E5%83%8F%20%2F%20%E4%B8%8D%E5%83%8F%22%5D%0A%20%20T%20--%3E%20V%0A%20%20E%20--%3E%20V%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"水印改变 token 采样的绿色列表，密钥未知则难以抹掉且难以伪造（在假设内）。微调、改温度、转写会衰减信号，验证要报功效。错误谱依赖「教师特有的失败」在蒸馏中被模仿——提取越成功，指纹越容易命中，这是故意的。",-1)),(e(),B(A,null,{default:E(()=>[o(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E4%B8%8A%E4%B8%80%E4%B8%AA%20token%20%E7%9A%84%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%20--%3E%20H%5B%22%E7%94%A8%E5%AF%86%E9%92%A5%E5%93%88%E5%B8%8C%E5%87%BA%E7%BB%BF%E8%89%B2%E8%AF%8D%E8%A1%A8%22%5D%0A%20%20H%20--%3E%20B%5B%22%E9%87%87%E6%A0%B7%E6%97%B6%E5%81%8F%E7%BD%AE%EF%BC%9A%E7%BB%BF%E8%89%B2%20token%20%E6%9B%B4%E5%AE%B9%E6%98%93%E8%A2%AB%E9%80%89%22%5D%0A%20%20B%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E6%96%87%E6%9C%AC%22%5D%0A%20%20OUT%20--%3E%20CHK%7B%22%E9%AA%8C%E8%AF%81%E6%96%B9%E6%98%AF%E5%90%A6%E6%8C%81%E6%9C%89%E5%AF%86%E9%92%A5%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%8C%81%E6%9C%89%22%7C%20Y%5B%22%E7%BB%9F%E8%AE%A1%E7%BB%BF%E8%89%B2%E8%AF%8D%E5%8D%A0%E6%AF%94%EF%BC%8C%E6%98%BE%E8%91%97%E5%81%8F%E9%AB%98%E5%8D%B3%E5%88%A4%E3%80%8E%E5%83%8F%E3%80%8F%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20N%5B%22%E7%9C%8B%E4%B8%8D%E5%87%BA%E8%A7%84%E5%BE%8B%EF%BC%8C%E9%9A%BE%E4%BB%A5%E6%8A%B9%E9%99%A4%E4%B9%9F%E9%9A%BE%E4%BB%A5%E4%BC%AA%E9%80%A0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">数字实例：设不加偏置时每个位置选到绿色词的概率约 50%。嵌水印后若稳定到 55%，单看一句什么都说明不了；但几千个 token 的文本上，这个差值足以把误报率压到极低。结论是统计性的——报的是显著性水平，不是「找到了某个暗号」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指纹不能替代访问控制。秘密触发若泄漏，就变成可被滥用的后门，必须当密钥管。<span class="marginnote">常见误区：初学者容易把指纹当「铁证」，宣称对方偷了权重。指纹证明的是行为像——微调、合并、量化都可能让信号衰减，所以正规结论要报检测功效与置信度，慎用「就是原权重」这类断言。</span>下一课安全等级把「危险能力是否可被提取到无门控学生」写进部署政策，指纹只是检测手段之一。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指纹：水印、秘密触发、私有错误谱。</li><li>证明「像」，慎称「就是原权重」。</li><li>密钥与私有集是生命线；公共基准不是指纹。</li><li>出处：水印课；提取课。</li></ul>',5))])}const g=i(p,[["render",m]]);export{_ as __pageData,g as default};
